test('invoiceTotals on real invoice from createInvoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.ok(invoiceResult.ok);
  const totalsResult = invoiceTotals(invoiceResult.value);
  assert.ok(totalsResult.ok);
  const { subtotal, discount, total } = totalsResult.value;
  assert.equal(typeof subtotal, 'number');
  assert.equal(typeof discount, 'number');
  assert.equal(typeof total, 'number');
  assert.ok(subtotal > 0);
  assert.ok(discount > 0);
  assert.ok(total < subtotal);
});

